<?php
declare(strict_types=1);namespace App\Interface\Http\Discovery;use App\Application\Discovery\DTO\Request\CreateDiscoverySearchRequestDto;use InvalidArgumentException;use Psr\Http\Message\ServerRequestInterface;final class DiscoveryRequestFactory{public function search(ServerRequestInterface $r):CreateDiscoverySearchRequestDto{try{$p=json_decode((string)$r->getBody(),true,512,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new InvalidArgumentException('JSON invalido.');}if(!is_array($p)||!is_string($p['query']??null)||!is_string($p['resource_type']??null)||!in_array($p['resource_type'],['EXAM','ANSWER_KEY'],true))throw new InvalidArgumentException('Consulta ou tipo invalido.');return new CreateDiscoverySearchRequestDto($p['query'],$p['resource_type']);}}
